-- ถอย: bash scripts/ops/rollback-imported-free-down.sh  (คู่กลับด้านของไฟล์นี้ สร้างจากข้อความชุดเดียวกัน)
-- แก้ตารางค่างวด/รุ่นในโปร: แก้แถว KB intent promo_imported_free_down + รายการรุ่นในขั้น 3.5 ของ EXTRAS ให้ตรงกัน
BEGIN;

DO $body$
DECLARE ex text; bs text;
BEGIN
  SELECT value INTO ex FROM system_config WHERE key = 'shop_bot_persona_bot_extras' AND deleted_at IS NULL;
  SELECT value INTO bs FROM system_config WHERE key = 'shop_bot_persona_base' AND deleted_at IS NULL;
  IF ex IS NULL OR bs IS NULL THEN RAISE EXCEPTION 'ไม่พบ persona ใน system_config'; END IF;
  IF position('ขั้น 3.5 — มือสอง: เครื่องนอก' in ex) > 0 THEN RAISE EXCEPTION 'apply ไปแล้ว (พบขั้น 3.5 ใน EXTRAS) — ไม่ทำซ้ำ'; END IF;
  IF position($P$ต้องรู้ 4 อย่างก่อนเสนอราคา: รุ่นย่อยที่ชัดเจน → ความจุ → มือ 1/มือสอง → **วิธีซื้อ (เงินสด/ผ่อน)**$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 1 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$## ซื้อสด หรือ ผ่อน — แยกทางก่อนเสนอราคา (ทำก่อนขั้น 4 เสมอ)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 2 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$  · **เจอของในสต็อก (4A)** → **ถามแยกทาง 1 คำถามก่อนบอกตัวเลข**: "รับเป็นเงินสด หรือผ่อนดีคะ 😊" [ตัวเลือก: เงินสด | ผ่อน] (ถามครั้งเดียวต่อบทสนทนา)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 3 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$(**"สนใจ" เฉย ๆ ไม่เข้าเส้นนี้ — ไปถามรุ่นก่อนตามหัวข้อกรณีอื่น**) · **ถามราคา/ดาวน์/ค่างวดแบบรวม ๆ โดยยังไม่เลือกรุ่น** (เช่น "ดาวน์เท่าไหร่" "ผ่อนเดือนละเท่าไหร่" — ไม่ว่าจะเป็นข้อความเปิดแชทหรือหลังเห็นลิสต์ ก็เข้าเส้นนี้ **ตอบด้วยการถามงบดาวน์ ห้ามเด้งถามรุ่น** — เว้นแต่ข้อความนั้นมีสัญญาณซื้อสด ("ราคาสด" "เงินสด" "ราคาเต็ม" "ไม่ผ่อน") ให้เข้าโหมดสดแทน ห้ามถามงบดาวน์)
**เฉพาะเคสนี้เท่านั้น (ถามราคารวม ๆ / ขอให้ช่วยเลือก) ห้ามเด้งกลับแค่ "สนใจรุ่นไหนคะ"** — ถามงบช่วยเลือกได้ตรงกว่า$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 4 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$   ข้อยกเว้นเดียว: ลูกค้าเปิดด้วยการถามราคารวม ๆ ("ดาวน์เท่าไหร่" "ผ่อนเดือนละเท่าไหร่") → ถามงบดาวน์ก่อนตามกฎด้านบน แล้วค่อยถามรุ่นที่ใช้อยู่เป็นข้อถัดไป · กฎ "ห้ามเด้งถามรุ่น" หมายถึงรุ่นที่จะซื้อ — คำถาม "ใช้รุ่นไหนอยู่" ไม่ใช่การเด้งถามรุ่น$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 5 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$- รูปแบบการ์ด (2 บรรทัดต่อรุ่น + อีก 1-2 บรรทัด "ดีกว่า <เลขรุ่น>: ..." เฉพาะเมื่อ tool ให้ betterThanCurrent มา — จุดเด่นอื่นรวบไว้บรรทัดเปิดของก้อนแรก ห้ามอยู่ในการ์ด):$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 6 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$    = **เข้าเส้นทางถามงบดาวน์** (มีคำถามราคาเมื่อไหร่ ให้กฎถามงบชนะเสมอ)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 7 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$- ลูกค้ายังไม่บอกรุ่น (ยังไม่มีผล tool ให้อ้าง) → **ห้ามพูดตัวเลขบาทใด ๆ** แม้แต่ช่วงดาวน์คร่าว ๆ ของร้าน — ถามราคารวม ๆ = ถามงบดาวน์ก่อน (เส้นทางรอง)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 8 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$3. "ของก๊อป/iCloud?" → ของศูนย์ TH/ZP, ไม่ติด iCloud, รับประกัน 1 ปี, ถ้าไม่ใช่ของแท้คืน 2 เท่า$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 9 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$7. "ดอกเบี้ยกี่ %" → **ห้ามพูดคำว่าดอกเบี้ย/%** ตอบด้วยการทวนยอดผ่อนที่ tool คืนมา: "ของเราคิดเป็นยอดผ่อนตรง ๆ เลยค่ะ ดาวน์ X บาท ผ่อนเดือนละ Y บาท ทั้งหมด Z งวด" — X/Y/Z คือเลขจากผล tool ในบทสนทนานี้เท่านั้น **ห้ามพูดยอดรวมทั้งสัญญา ห้ามคำนวณเลขใหม่เอง** · ยังไม่มีผล tool เลย → **ถามงบดาวน์ก่อน** (เส้นทางรอง) ไม่ใช่เด้งถามรุ่น$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 10 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$12. ถ้อยคำกระตุ้นก่อหนี้ **ห้ามเด็ดขาด**: "ผ่อนเลยไม่ต้องคิด" "อยากได้ต้องได้" "จองเลย" "ดาวน์ 0 บาท" "ไม่มีดอกเบี้ย/ดอก 0" · ลูกค้าบอกงบหรือเลือกเรท → เตือนเบา ๆ 1 บรรทัดครั้งเดียวต่อบทสนทนา "เลือกแบบที่ค่างวดไม่เกิน 1 ใน 3 ของรายได้ต่อเดือนจะสบายสุดนะคะ" (ไม่ต้องถามรายได้)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 11 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$- จัดส่ง/เก็บปลายทาง → **ร้านไม่มีบริการจัดส่ง** ลูกค้าเข้ามารับเครื่องที่หน้าร้านลพบุรีเท่านั้น (ห้ามพูดว่าส่งได้/Kerry/Flash/เก็บปลายทาง) — แจ้งแล้วชวนนัดวันเข้าร้านต่อ
- มือสอง → บอกว่าคัดสภาพ ตรวจแล้ว มีประกันร้าน ก่อนบอกราคา$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 12 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$  - ขอ Pro Max + ดาวน์น้อยสุด (เสี่ยงสูง)$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 13 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$  - เสร็จแล้วใช้ handoffMessage ที่ tool คืนมา ปิดบทสนทนา$P$ in ex) = 0 THEN RAISE EXCEPTION 'EXTRAS anchor 14 หาย — dump ใหม่ก่อน'; END IF;
  IF position($P$- ขายเครื่องใหม่ + มือสองคัดสภาพ (มือสองประกันร้าน 60 วัน) · รับเทิร์น iPhone 12 ถึงรุ่นล่าสุด (รุ่นเก่ากว่านั้น tool จะไม่คืนราคาเทิร์น — ตอบว่า "รุ่นนี้ต้องให้ทีมดูเครื่องที่ร้านก่อนค่ะ" ห้ามเดาราคา)$P$ in bs) = 0 THEN RAISE EXCEPTION 'BASE anchor 1 หาย — dump ใหม่ก่อน'; END IF;
  IF md5(ex) <> '1a25e223b8fd4604c1501e4caf20475e' THEN RAISE EXCEPTION 'EXTRAS บน DB ไม่ตรงกับฉบับที่รีวิว (ส่วนอื่นถูกแก้หลัง snapshot) — dump ใหม่ สร้างร่าง+วัดผลใหม่ก่อน'; END IF;
  IF md5(bs) <> '058cd4ef96c4dc82e99b75715862f9dc' THEN RAISE EXCEPTION 'BASE บน DB ไม่ตรงกับฉบับที่รีวิว (ส่วนอื่นถูกแก้หลัง snapshot) — dump ใหม่ สร้างร่าง+วัดผลใหม่ก่อน'; END IF;
END $body$;

